mkdir -p /app/bin /app/out; cat > /app/bin/fees.py <<'EOF'
#!/usr/bin/env python3
import sys, os, csv, json, re, configparser
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WD = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def cents(s):
    return int((Decimal(str(s).strip()) * 100).to_integral_value())


def pnum(s):
    d = re.sub(r"\D", "", str(s))
    return int(d) if d else 0


def pdate(s):
    return date.fromisoformat(s.strip())


def parse_off(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s)
    sign = -1 if m.group(1) == "-" else 1
    return sign * (int(m.group(2)) * 60 + int(m.group(3)))


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        rd = csv.DictReader(f)
        rows = []
        for r in rd:
            rows.append({(k or "").strip(): (v or "").strip() for k, v in r.items()})
        return rows


def main(inp, outp):
    cp = configparser.ConfigParser(interpolation=None)
    with open(os.path.join(inp, "policy.ini"), encoding="utf-8-sig") as f:
        cp.read_file(f)
    library = cp["statement"]["library"].strip()
    pstart = pdate(cp["statement"]["period_start"])
    pend = pdate(cp["statement"]["period_end"])
    base_off = parse_off(cp["clock"]["offset"])
    changes = []
    ch = cp["clock"].get("changes", "").strip()
    for part in ch.split(";"):
        part = part.strip()
        if not part:
            continue
        t, o = part.split()
        t = datetime.strptime(t, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
        changes.append((t, parse_off(o)))
    changes.sort()
    items = {}
    cats = {}
    for sec in cp.sections():
        if sec.lower().startswith("item:"):
            s = cp[sec]
            items[sec[5:].strip().lower()] = dict(
                name=sec[5:].strip(), loan_days=int(s["loan_days"]), renewals=int(s["renewals"]),
                grace=int(s["grace_days"]), daily=cents(s["daily"]), cap=cents(s["loan_cap"]))
        elif sec.lower().startswith("category:"):
            s = cp[sec]
            sc = s.get("statement_cap", "none").strip()
            cats[sec[9:].strip().lower()] = dict(
                name=sec[9:].strip(), cap=None if sc.lower() == "none" or not sc else cents(sc),
                discount=int(s.get("discount", "0").strip() or 0),
                exempt={x.strip().lower() for x in s.get("exempt", "").split(",") if x.strip()})

    branches = read_csv(os.path.join(inp, "branches.csv"))
    open_days = {}
    border = []
    for b in branches:
        bid = b["branch"].strip().upper()
        border.append(bid)
        open_days[bid] = {w.strip().lower()[:3] for w in b["open_days"].split()}
    cal = {}
    for r in read_csv(os.path.join(inp, "calendar.csv")):
        d = r["date"]
        if ".." in d:
            a, z = d.split("..")
        else:
            a = z = d
        cal.setdefault(r["branch"].strip().upper() if r["branch"].strip() != "*" else "*", []).append(
            (pdate(a), pdate(z), r["status"].strip().lower()))

    def is_open(br, d):
        for key in (br, "*"):
            for a, z, st in cal.get(key, []):
                if a <= d <= z:
                    return st == "open"
        return WD[d.weekday()] in open_days.get(br, set())

    def next_open(br, d):
        for _ in range(3660):
            if is_open(br, d):
                return d
            d += timedelta(days=1)
        return d

    prow = {}
    pname = {}
    for r in read_csv(os.path.join(inp, "patrons.csv")):
        n = pnum(r["patron"])
        prow.setdefault(n, []).append((pdate(r["since"]), r["category"].strip()))
        pname.setdefault(n, r["patron"].strip())
    for n in prow:
        prow[n].sort(key=lambda x: x[0])

    def category(n, d):
        rows = prow[n]
        c = rows[0][1]
        for s, cat in rows:
            if s <= d:
                c = cat
        return cats[c.lower()]

    waivers = []
    for r in read_csv(os.path.join(inp, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((pnum(r["patron"]), r["loan"].strip(), None if v.lower() == "full" else cents(v)))

    # events
    def local_from_instant(s):
        s = s.strip()
        m = re.fullmatch(r"(\d{4}-\d\d-\d\d)[T ](\d\d:\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?", s)
        dt = datetime.strptime(m.group(1) + " " + m.group(2), "%Y-%m-%d %H:%M")
        z = m.group(4)
        off = 0 if (z is None or z == "Z") else parse_off(z)
        utc = (dt - timedelta(minutes=off)).replace(tzinfo=timezone.utc)
        lo = base_off
        for t, o in changes:
            if t <= utc:
                lo = o
        return (utc + timedelta(minutes=lo)).replace(tzinfo=None)

    events = {}
    edir = os.path.join(inp, "exports")
    for fn in sorted(os.listdir(edir)):
        path = os.path.join(edir, fn)
        low = fn.lower()
        if low.endswith(".csv"):
            recs = read_csv(path)
            for r in recs:
                r["_t"] = datetime.strptime(r["time"][:16], "%Y-%m-%d %H:%M")
        elif low.endswith(".jsonl"):
            recs = []
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    r = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                    r["_t"] = local_from_instant(r["at"])
                    recs.append(r)
        else:
            continue
        for r in recs:
            if r.get("event"):
                events.setdefault(r["event"], r)

    cancelled = set()
    for e in events.values():
        if e.get("type", "").lower() == "void":
            cancelled.add(e.get("target", ""))
    live = [e for k, e in events.items() if k not in cancelled and e.get("type", "").lower() != "void"]

    checkouts = {}
    later = {}
    for e in live:
        t = e["type"].lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            later.setdefault(e["loan"], []).append(e)

    loans = []
    for lid, c in checkouts.items():
        cd = c["_t"].date()
        if cd > pend:
            continue
        it = items[c["item_type"].lower()]
        br = c["branch"].upper()
        due = next_open(br, cd + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for e in sorted(later.get(lid, []), key=lambda e: e["_t"]):
            ld = e["_t"].date()
            if e["type"].lower() == "renew":
                if ld <= due and nren < it["renewals"] and ld <= pend:
                    nren += 1
                    due = next_open(br, ld + timedelta(days=it["loan_days"]))
            else:
                ret = ld - timedelta(days=1) if e.get("via", "").lower() == "dropbox" else ld
                break
        if ret is not None and ret < pstart:
            continue
        returned = ret if (ret is not None and ret <= pend) else None
        end = returned if returned else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od < 1:
            continue
        charged = od if od > it["grace"] else 0
        n = pnum(c["patron"])
        cat = category(n, cd)
        base = charged * it["daily"]
        if it["name"].lower() in cat["exempt"]:
            base = 0
        base = min(base, it["cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        waived = 0
        full = False
        tot = 0
        for wp, wl, wv in waivers:
            if wp == n and (wl == "*" or wl == lid):
                if wv is None:
                    full = True
                else:
                    tot += wv
        waived = assessed if full else min(tot, assessed)
        loans.append(dict(loan=lid, item=c.get("item", ""), item_type=it["name"], branch=br,
                          checkout=cd, due=due, returned=returned, overdue_days=od,
                          charged_days=charged, assessed=assessed, waived=waived, capped=0,
                          billed=assessed - waived, _p=n))

    bypat = {}
    for l in loans:
        bypat.setdefault(l["_p"], []).append(l)
    statements = []
    for n in sorted(bypat):
        ls = sorted(bypat[n], key=lambda l: (l["due"], l["loan"]))
        cat = category(n, pend)
        if cat["cap"] is not None:
            excess = sum(l["billed"] for l in ls) - cat["cap"]
            if excess > 0:
                for l in sorted(ls, key=lambda l: (l["due"], l["loan"]), reverse=True):
                    g = min(excess, l["billed"])
                    l["capped"] = g
                    l["billed"] -= g
                    excess -= g
                    if excess <= 0:
                        break
        out = []
        for l in ls:
            o = {k: v for k, v in l.items() if k != "_p"}
            for k in ("checkout", "due", "returned"):
                o[k] = o[k].isoformat() if o[k] else None
            out.append(o)
        st = dict(patron=pname[n], category=cat["name"], loans=out)
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(l[k] for l in ls)
        statements.append(st)

    bsum = []
    for b in border:
        ls = [l for l in loans if l["branch"] == b]
        s = dict(branch=b, loans=len(ls))
        for k in ("charged_days", "assessed", "waived", "capped", "billed"):
            s[k] = sum(l[k] for l in ls)
        bsum.append(s)
    res = dict(library=library, period={"start": pstart.isoformat(), "end": pend.isoformat()},
               statements=statements, branches=bsum)
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, indent=2, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
EOF
cd /app; python3 bin/fees.py data out/statements.json && python -m unittest discover -s tests -t . 2>&1 | tail -15; python tools/check_fees.py | tail -15
